import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const f=JSON.parse('{"title":"FR 3.7.17 — Update Collaborator Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/06-ai-features/3-7-17-update-collaborator-profile/spec.md","filePath":"feature/srs/06-ai-features/3-7-17-update-collaborator-profile/spec.md"}'),d={name:"feature/srs/06-ai-features/3-7-17-update-collaborator-profile/spec.md"};function n(c,e,i,l,s,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-7-17-—-update-collaborator-profile" tabindex="-1">FR 3.7.17 — Update Collaborator Profile <a class="header-anchor" href="#fr-3-7-17-—-update-collaborator-profile" aria-label="Permalink to &quot;FR 3.7.17 — Update Collaborator Profile&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.7.17</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-104</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Update Collaborator Profile</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">AI Features (<code>3.7</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20</code>, <code>BR-51</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01</code>, <code>MSG02</code>, <code>MSG03</code>, <code>MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Consolidates <code>partner-directory</code> DA-949)</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Enable authorized <code>Owner</code> (and <code>Manager</code> within permitted collaborator endpoints) to update an existing Collaborator Profile&#39;s name, category, rate-card benchmarks, notes, and <code>contactInfo</code> JSONB fields in <code>third_party_collaborators</code> using optimistic concurrency control (<code>expectedVersion</code> -&gt; <code>version + 1</code>), while strictly preserving immutable audit markers (<code>agency_id</code>, <code>first_used_at</code>, <code>usage_history_verified</code>) and unknown legacy <code>contactInfo</code> JSON keys (<code>BR-51</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an <code>Owner</code> or <code>Manager</code>, I want to update a collaborator&#39;s contact person, phone/email, rate card, or specialty tags without losing historical Campaign links or overwriting concurrent edits made by another session.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Agency Immutability &amp; Role Check (<code>BR-20</code>):</strong> Collaborator <code>{id}</code> must belong to <code>{agencyId}</code>; <code>agency_id</code> can never be mutated to transfer a partner across Agencies (<code>403</code>/<code>404</code>, <code>MSG01</code>, <code>MSG07</code>).</li><li><strong>Optimistic Concurrency (<code>expectedVersion</code>):</strong> <code>PATCH /api/v1/agencies/{agencyId}/collaborators/{id}</code> validates <code>expectedVersion</code> against <code>third_party_collaborators.version</code>. Stale edits (including when a concurrent Campaign first-assign incremented <code>version</code> and stamped <code>first_used_at</code>) fail deterministically with <code>409 CONFLICT</code> rather than silently overwriting state.</li><li><strong>Non-Destructive JSONB Contact Merge (<code>BR-51</code>):</strong> Updating <code>contactInfo</code> validates known fields (<code>contactPerson</code>, <code>email</code>, <code>phone</code> 7–15 digits, <code>http/https</code> <code>website</code>) and merges them while preserving any unrecognized legacy JSON keys already stored on the row.</li><li><strong>Read-Only Lifecycle Markers:</strong> <code>first_used_at</code>, <code>usage_history_verified</code>, and <code>is_active</code> are mapped read-only for profile edit payloads; Campaign approvals and <code>campaign_collaborators.cooperation_status</code> are untouched by profile edits.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Edit drawer/dialog headers, optimistic conflict banners, and save actions use synchronized <code>collaborators.edit.*</code> and <code>collaborators.errors.versionConflict</code> keys in <code>vi.json</code> and <code>en.json</code>.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> Edit form (<code>PartnerForm.tsx</code>, <code>PartnerDetails.tsx</code>) and conflict alerts render cleanly in Light and Dark themes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Components:</strong> <code>pages/collaborators/components/PartnerForm.tsx</code>, <code>PartnerDetails.tsx</code>, <code>PartnerContactFields.tsx</code>.</li><li><strong>Mobile Screen:</strong> <code>src/screens/agency/AgencyCollaboratorsScreen.tsx</code> edit sheet.</li><li><strong>UI States:</strong><ul><li><strong>Prefilled Ready:</strong> Loads current <code>version</code> and structured contact fields while keeping extra JSON keys in state.</li><li><strong>Saving:</strong> Disables inputs and shows spinner on Save CTA.</li><li><strong>Version Conflict (<code>409</code>):</strong> Displays localized reload prompt so user can refresh latest partner state without losing awareness of concurrent changes.</li><li><strong>Success:</strong> Updates detail view and directory list cache immediately with localized confirmation toast.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth</th><th style="text-align:left;">Handler</th><th style="text-align:left;">Request / Response</th></tr></thead><tbody><tr><td style="text-align:left;"><code>PATCH /api/v1/agencies/{agencyId}/collaborators/{id}</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>DirectoryPartnerController.update()</code></td><td style="text-align:left;">Req: <code>UpdateDirectoryPartnerRequest</code> (<code>expectedVersion</code>, <code>name</code>, <code>type</code>, <code>contactInfo</code>, <code>notes</code>) -&gt; <code>200 ApiResponse&lt;DirectoryPartnerResponse&gt;</code></td></tr><tr><td style="text-align:left;"><code>PUT /api/v1/collaborators/{collaboratorId}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager</code>)</td><td style="text-align:left;"><code>CollaboratorController.update()</code></td><td style="text-align:left;">Req: <code>UpdateCollaboratorRequest</code> -&gt; <code>200 ApiResponse&lt;CollaboratorResponse&gt;</code></td></tr><tr><td style="text-align:left;"><code>PUT /api/v1/collaborators/campaign/{campaignCollaboratorId}/cooperation</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager</code>)</td><td style="text-align:left;"><code>CollaboratorController</code> / <code>CampaignCollaboratorController</code></td><td style="text-align:left;">Updates per-campaign cooperation status independently of master directory row</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>VERSION_CONFLICT</code> (<code>409</code>, <code>MSG03</code>): Concurrent edit or concurrent first-time Campaign assignment bumped <code>version</code>; prevents wiping <code>first_used_at</code>.</li><li><code>PARTNER_NOT_FOUND</code> (<code>404</code>, <code>MSG01</code>): Partner deleted prior to edit or belongs to another Agency.</li><li><strong>Editing Inactive Partner:</strong> Permitted in management directory (e.g., updating archival notes) while <code>isActive</code> remains <code>false</code>.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Sibling SRS FRs:</strong> <a href="./../3-7-15-view-collaborator-directory/spec.html">FR 3.7.15 — View Collaborator Directory</a> · <a href="./../3-7-16-create-collaborator-profile/spec.html">FR 3.7.16 — Create Collaborator Profile</a> · <a href="./../3-7-18-remove-collaborator-profile/spec.html">FR 3.7.18 — Remove Collaborator Profile</a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/06-ai-features.html">BA 3.7 AI Features</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Optimistic locking (<code>version</code>), JSONB unknown-key preservation, read-only marker protection, <code>vi</code>/<code>en</code> i18n, and Light/Dark UI verified in <a href="./test.html">test.md</a>.</li><li><strong>Out of Scope:</strong> Reactivating a deactivated partner (<code>isActive: false -&gt; true</code>) without a separate BA-approved workflow.</li></ul>',19)])])}const h=t(d,[["render",n]]);export{f as __pageData,h as default};
